fn make_in_flight(
    event: SubmitEvent,
    comment_ids: &[&str],
    head_sha: &str,
    moved_to_summary_count: usize,
) -> SubmitInFlightState {
    let mappable = comment_ids
        .iter()
        .enumerate()
        .map(|(i, id)| crate::forge::submit::InlineComment {
            path: PathBuf::from("src/lib.rs"),
            line: 11 + i as u32,
            side: crate::forge::submit::GhSide::Right,
            counterpart_line: None,
            start_line: None,
            start_side: None,
            old_path: None,
            body: "x".to_string(),
            comment_id: (*id).to_string(),
        })
        .collect();
    SubmitInFlightState {
        event,
        mappable,
        summary_comment_ids: Vec::new(),
        review_comment_ids: Vec::new(),
        legacy_fallback_comment_ids: Vec::new(),
        moved_to_summary_count,
        head_sha_snapshot: head_sha.to_string(),
